_FALLBACK_SRC = '# Exact action format: "[(from_node, to_node, count), ...]"\n# Payout: "a > b": full reward; "a == b >= 1": reward / 2 each;\n# "a == b == 0": nothing happens and the order stays open.\n# Cost: "UPKEEP = 1.0" per unit away from its own base per turn.\n# Units move at most one edge per turn, using start-of-turn units only.\n\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 60\nUPKEEP = 1.0\n\n\ndef order_payout(reward, own_count, opponent_count):\n    """Exact revenue to us from one order after movement."""\n    if own_count > opponent_count:\n        return float(reward)\n    if own_count == opponent_count and own_count >= 1:\n        return float(reward) / 2.0\n    return 0.0\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [-1] * n\n        distance[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if distance[neighbor] == -1:\n                    distance[neighbor] = distance[node] + 1\n                    queue.append(neighbor)\n        distances.append(distance)\n    return adjacency, distances\n\n\ndef conservative_plan(obs, adjacency, distances):\n    """\n    Only take orders that can be collected THIS turn.\n\n    This deliberately forgoes distant opportunities: no unit ever leaves home\n    merely on the promise of a future payment. Unassigned deployed units head\n    straight home. Each accepted payment comfortably covers this turn and the\n    entire subsequent recall, even with no further orders.\n\n    Against an idle opponent, each excursion therefore earns strictly more\n    than its complete upkeep cost. Multiple orders at a node need only one\n    unit. There is no speculative stationing or reinforcement.\n    """\n    n = len(adjacency)\n    home = int(obs["player_base"])\n    own = list(obs["player_units"])\n    enemy = obs["opponent_units"]\n    turns_remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    if turns_remaining == 0:\n        return []\n\n    rewards = [0.0] * n\n    for node, reward, turns_left in obs.get("orders", []):\n        if turns_left >= 1:\n            rewards[node] += float(reward)\n\n    # Avoid even a possible immediate fight. This includes enemy units that\n    # could arrive from their base; we never pay to win an arms race.\n    enemy_can_arrive = [\n        enemy[node] + sum(enemy[v] for v in adjacency[node])\n        for node in range(n)\n    ]\n\n    candidates = []\n    for target in range(n):\n        if target == home or rewards[target] <= 0.0:\n            continue\n        if enemy_can_arrive[target] != 0:\n            continue\n        home_distance = distances[target][home]\n        if home_distance < 0:\n            continue\n\n        # A unit at distance h costs 1 now, then at most h-1 on\n        # shortest-path recall. Use h+1 as a deliberately conservative bound.\n        full_cost_bound = UPKEEP * min(\n            turns_remaining, 1 + home_distance\n        )\n        payout = order_payout(rewards[target], 1, 0)\n        if payout <= full_cost_bound + 1.0:\n            continue\n\n        # Nearest-to-home jobs first, followed by their certain net payout.\n        candidates.append(\n            (home_distance, -(payout - full_cost_bound), target)\n        )\n    candidates.sort()\n\n    available = own[:]\n    plan = []\n    for _, _, target in candidates:\n        sources = [target] + adjacency[target]\n        feasible = [s for s in sources if available[s] > 0]\n        if not feasible:\n            continue\n\n        # Reuse a deployed unit before launching another one. Prefer staying\n        # at the target, then units that are expensive to recall.\n        source = min(\n            feasible,\n            key=lambda s: (\n                s == home,\n                s != target,\n                -distances[s][home],\n                s,\n            ),\n        )\n        available[source] -= 1\n        if source != target:\n            plan.append((source, target, 1))\n\n    # Reserved units stay at their job; every other deployed unit returns.\n    for source in range(n):\n        count = available[source]\n        if count <= 0 or source == home:\n            continue\n        distance = distances[source][home]\n        if distance <= 0:\n            continue\n        next_node = next(\n            (v for v in adjacency[source]\n             if distances[v][home] == distance - 1),\n            None,\n        )\n        if next_node is not None:\n            plan.append((source, next_node, count))\n    return plan\n\n\ndef validated_action(plan, start_units, adjacency):\n    """Replay moves using only still-unused start-of-turn units."""\n    n = len(adjacency)\n    available = [int(c) for c in start_units]\n    aggregated = {}\n    for source, target, requested in plan:\n        source, target, requested = int(source), int(target), int(requested)\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if source == target or target not in adjacency[source]:\n            continue\n        count = min(max(0, requested), available[source])\n        if count <= 0:\n            continue\n        available[source] -= count\n        key = (source, target)\n        aggregated[key] = aggregated.get(key, 0) + count\n\n    return [\n        (int(source), int(target), int(count))\n        for (source, target), count in sorted(aggregated.items())\n    ]\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_cache = {}\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        edges = tuple((int(a), int(b)) for a, b in obs.get("edges", []))\n        key = (n, edges)\n        if key not in self._map_cache:\n            self._map_cache[key] = preprocess_map(n, edges)\n        adjacency, distances = self._map_cache[key]\n        plan = conservative_plan(obs, adjacency, distances)\n        return validated_action(plan, obs["player_units"], adjacency)\n'
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
